    C3DVector s = a.CrossProduct(a);
    CHECK(s.X == 0.0f && s.Y == 0.0f && s.Z == 0.0f);
    C3DVector h(0.5f, -1.5f, 2.0f), k(4.0f, 0.25f, -1.0f);
